function [y] = unit_clip(x)
%UNIT_CLIP  x.min(1).max(-1) of the code (MATLAB's max(min(x, 1), -1)): a nan gives 1.
%   x: real[1] (passed a plain number)
%   returns y: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = 0;
    m = asils.pc.choose((x < 1), x, 1);
    y = asils.pc.choose((m > (-(1))), m, (-(1)));
end
